"""Engine port for the shared A2A server.

The executor, output channel, and agent card talk to an engine only through
:class:`A2AEngineAdapter`. CALM and Mantle each implement it. This module does
not import ``rasa.mantle``, flows, or ``Domain``.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Any, Protocol

from a2a.server.tasks.task_updater import TaskUpdater
from a2a.types import AgentSkill, Message
from pydantic import BaseModel, ConfigDict

from rasa.core.a2a_server.config import A2AServerSettings
from rasa.core.a2a_server.task_state_mapper import TaskStateMappingResult
from rasa.shared.exceptions import RasaException

if TYPE_CHECKING:
    from a2a.types import Message as A2AMessage

    from rasa.core.a2a_server.a2a_output_channel import A2AOutputChannel
    from rasa.core.a2a_server.startup import A2AServerStartup
    from rasa.core.agent import Agent
    from rasa.core.processor import MessageProcessor
    from rasa.shared.core.trackers import DialogueStateTracker


class PreparedA2AInput(BaseModel):
    """User text and metadata after an engine has read structured input."""

    model_config = ConfigDict(frozen=True)

    text: str
    metadata: dict[str, Any]


class EngineCancelResult(BaseModel):
    """Dialogue outcome of an orchestrator cancel.

    The A2A task state is still ``canceled``. ``canceled_skill`` is Mantle
    status data: the user-facing skill this cancel dropped. It is empty when
    this cancel did not drop one, including a CALM cancel.
    """

    model_config = ConfigDict(frozen=True)

    canceled_skill: str | None = None


class A2AEngineAdapter(Protocol):
    """What the shared A2A core asks an engine to do.

    The methods speak A2A types. Engine-only options are constructor arguments
    of the implementation, not fields on :class:`A2AServerSettings`.
    """

    async def get_card_skills(self) -> list[AgentSkill]:
        """Skills advertised on the generated AgentCard."""
        ...

    def pattern_replies_are_user_facing(self) -> bool:
        """Whether pattern bot utterances are sent like any other reply.

        When this is false, the channel keeps those utterances out of
        user-facing parts, and an orchestrator cancel also hides
        ``pattern_cancel_flow`` utterances.
        """
        ...

    def prepare_input(
        self,
        message: "A2AMessage | None",
        text: str,
        metadata: dict[str, Any],
    ) -> PreparedA2AInput:
        """Turn orchestrator slot or memory payload into engine input.

        The caller strips injected internal metadata keys before this runs.
        """
        ...

    def map_task_state(
        self,
        tracker: "DialogueStateTracker",
        *,
        outcome: Any | None = None,
        orchestrator_cancel: bool = False,
    ) -> TaskStateMappingResult:
        """Map the engine's turn result to an A2A task state.

        ``outcome`` is whatever the engine passed to
        ``OutputChannel.record_turn_outcome``. CALM ignores it. Mantle reads
        the turn's error, cancel, and hangup flags from it.
        """
        ...

    def uses_latest_action_for_turn_end(self) -> bool:
        """Whether a leftover ``working`` state may be closed from ``latest_action``.

        CALM does this. Mantle does not: its only fallback is ``failed`` /
        ``turn_incomplete``, and it must not read ``latest_action_name``.
        """
        ...

    async def build_status_data(
        self,
        mapping: TaskStateMappingResult,
        tracker: "DialogueStateTracker | None",
        *,
        updater: TaskUpdater,
        user_visible_text: str | None = None,
        conversation_repair_agent_utterances: list[str] | None = None,
    ) -> Message | None:
        """Build the status message for a terminal or interactive-terminal state."""
        ...

    async def cancel_active_work(
        self,
        sender_id: str,
        output_channel: "A2AOutputChannel",
    ) -> EngineCancelResult:
        """Stop the engine's active work and publish ``canceled``.

        The returned skill is the one this cancel dropped. The publisher uses
        that value instead of reading ``SkillCancelled`` back out of the turn.
        """
        ...

    def validate_startup(
        self,
        settings: A2AServerSettings,
        processor: "MessageProcessor",
    ) -> None:
        """Reject a loaded model whose session config cannot resume an A2A context."""
        ...


def build_a2a_engine_adapter_for_startup(
    agent: "Agent",
    startup: "A2AServerStartup",
) -> A2AEngineAdapter:
    """Build the adapter for the engine that already supplied *startup*.

    ``rasa.mantle`` is imported only when that engine is Mantle, so a CALM run
    never loads it.
    """
    from rasa.shared.engine_version import MANTLE_ENGINE_VERSION

    if startup.engine_version == MANTLE_ENGINE_VERSION:
        from rasa.mantle.a2a.engine_adapter import MantleA2AEngineAdapter
        from rasa.mantle.config.a2a_server import MantleA2AServerStartup

        if not isinstance(startup, MantleA2AServerStartup):
            raise RasaException(
                "Cannot build the Mantle A2A adapter: the loaded Mantle model "
                "has no Mantle A2A startup binding."
            )
        return MantleA2AEngineAdapter(
            agent, include_default_skills=startup.include_default_skills
        )

    from rasa.core.a2a_server.calm_engine_adapter import CalmA2AEngineAdapter
    from rasa.core.a2a_server.startup import CalmA2AServerStartup

    if not isinstance(startup, CalmA2AServerStartup):
        raise RasaException(
            "Cannot start the A2A server: the loaded CALM model has no CALM "
            "A2A startup binding."
        )
    return CalmA2AEngineAdapter(
        agent, include_conversation_repair=startup.include_conversation_repair
    )
